<?php require_once '../includes/auth.php';admin_required();$q=$pdo->query("SELECT a.*,u.name AS actor_name FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_user_id ORDER BY a.created_at DESC LIMIT 200");$logs=$q->fetchAll();$title='Audit log';require '../includes/header.php';?><h1>Audit log</h1><?php foreach($logs as $l):?><div class="card mb-2"><div class="card-body py-2"><strong><?=e($l['action'])?></strong> · <?=e($l['target_type'])?> #<?=e($l['target_id'])?><div class="small text-muted"><?=e($l['actor_name']??'System')?> · <?=e($l['created_at'])?></div><?php if($l['details']):?><div class="small mt-1"><?=e($l['details'])?></div><?php endif;?></div></div><?php endforeach;?><?php if(!$logs):?><p>No audit events yet.</p><?php endif;?><?php require '../includes/footer.php';?>